                "parity target, never accuracy-in-the-world; REL-006's >=95% floor is " +
                "9.9b's, instrumented by Tool 9 via 9.16."

        fun bitsToHex(bits: BooleanArray): String {
            val sb = StringBuilder((bits.size + 3) / 4)
            var i = 0
            while (i < bits.size) {
                var nibble = 0
                for (j in 0 until 4) {
                    if (i + j < bits.size && bits[i + j]) nibble = nibble or (1 shl j)
                }
                sb.append("0123456789abcdef"[nibble])
                i += 4
            }
            return sb.toString()
        }

        fun medianMs(ns: List<Long>): Double {
            if (ns.isEmpty()) return 0.0
            val s = ns.sorted()
            val mid = s.size / 2
            val v = if (s.size % 2 == 1) s[mid].toDouble() else (s[mid - 1] + s[mid]) / 2.0
            return v / 1e6
        }

        fun sha256Hex(b: ByteArray): String =
            java.security.MessageDigest.getInstance("SHA-256").digest(b)
                .joinToString("") { "%02x".format(it) }
    }
